#include <stdlib.h>

static int read_center(int n) {
    int *head = (int *)malloc((n + 1) * sizeof(int));
    int *to = (int *)malloc((2 * n) * sizeof(int));
    int *nxt = (int *)malloc((2 * n) * sizeof(int));

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
    }

    int ec = 0;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        to[ec] = b;
        nxt[ec] = head[a];
        head[a] = ec++;

        to[ec] = a;
        nxt[ec] = head[b];
        head[b] = ec++;
    }

    int *queue = (int *)malloc((n + 1) * sizeof(int));
    int *dist = (int *)malloc((n + 1) * sizeof(int));
    int *parent = (int *)malloc((n + 1) * sizeof(int));

    for (int i = 1; i <= n; i++) dist[i] = -1;

    int front = 0, rear = 0;
    int start = 1;
    queue[rear++] = start;
    dist[start] = 0;
    parent[start] = 0;

    int far = start;

    while (front < rear) {
        int u = queue[front++];

        if (dist[u] > dist[far]) far = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                queue[rear++] = v;
            }
        }
    }

    int a = far;

    for (int i = 1; i <= n; i++) dist[i] = -1;

    front = rear = 0;
    queue[rear++] = a;
    dist[a] = 0;
    parent[a] = 0;
    far = a;

    while (front < rear) {
        int u = queue[front++];

        if (dist[u] > dist[far]) far = u;

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                queue[rear++] = v;
            }
        }
    }

    int b = far;
    int diameter = dist[b];

    int cur = b;
    int steps = diameter - diameter / 2;
    for (int i = 0; i < steps; i++) {
        cur = parent[cur];
    }

    free(head);
    free(to);
    free(nxt);
    free(queue);
    free(dist);
    free(parent);

    return cur;
}

int main(void) {
    int N, M;
    scanf("%d %d", &N, &M);

    int c1 = read_center(N);
    int c2 = read_center(M);

    printf("%d %d\n", c1, c2);

    return 0;
}
